import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

/** Where document files live. Local disk now; phase 6 adds an S3 implementation. */
export interface FileStore {
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer>;
}

export function localFileStore(dir: string): FileStore {
  // Keys are generated by the API (document id + extension), never taken from the upload.
  const path = (key: string) => join(dir, key);
  return {
    async put(key, data) {
      await mkdir(dir, { recursive: true });
      await writeFile(path(key), data, { flag: 'wx' });
    },
    get: (key) => readFile(path(key)),
  };
}
